WITH supplier_stats AS (SELECT supplier_id, MIN(launch_date) AS min_launch_date, ROUND((100 * SUM(CASE WHEN brand = 'Initech' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_initech FROM products WHERE cost BETWEEN 330 AND 620 GROUP BY supplier_id) SELECT suppliers.id, suppliers.supplier_name, supplier_stats.min_launch_date, supplier_stats.pct_initech FROM suppliers JOIN supplier_stats ON suppliers.id = supplier_stats.supplier_id ORDER BY suppliers.supplier_name, id LIMIT 10
